package trace

import (
	"testing"
)

// TestBundleReplayFixtures decodes the fixture files generated by the
// *production rust encoder* (`runopsy-trace genfixtures`), which makes these
// tests a true cross-language check (6.44/6.56): if the rust schema drifts
// from go, these decode checks fail. regenerate by running:
//
//	cd trace-rs && ./target/debug/runopsy-trace genfixtures ../testdata/trace
//
// (makefile: make trace-fixtures).
func TestBundleReplayFixtures(t *testing.T) {
	collect := func(t *testing.T, path string) ([]TraceEvent, ReplayStats) {
		t.Helper()
		var evs []TraceEvent
		stats, err := ReplayFile(path, func(e TraceEvent) {
			evs = append(evs, e)
		})
		if err != nil {
			t.Fatalf("replay %s: %v", path, err)
		}
		return evs, stats
	}

	t.Run("process-exec", func(t *testing.T) {
		evs, stats := collect(t, "../../testdata/trace/process-exec.bin")
		if stats.Events != 1 || stats.Lost != 0 || stats.BadSamples != 0 {
			t.Fatalf("stats: %+v", stats)
		}
		e := evs[0]
		if e.Type != EventEXEC || e.PID != 8241 || e.PPID != 5001 {
			t.Fatalf("exec event: %+v", e)
		}
		if e.ExecPath != "/usr/local/bin/Runner.Worker" {
			t.Fatalf("exec path: %q", e.ExecPath)
		}
		if e.ExitCode != nil {
			t.Fatalf("exec must not carry exit code: %+v", e)
		}
	})

	t.Run("process-exit", func(t *testing.T) {
		evs, stats := collect(t, "../../testdata/trace/process-exit.bin")
		if stats.Events != 1 {
			t.Fatalf("stats: %+v", stats)
		}
		e := evs[0]
		// Kernel-signaled death: fact is the authority (6.14): the exit
		// record names signal 9, NOT a sender. no claim beyond that.
		if e.Type != EventEXIT || e.Signal != 9 || e.Fact != SignalDeliveredToExit {
			t.Fatalf("signaled exit: %+v", e)
		}
		if e.ExitCode != nil {
			t.Fatalf("signaled exit must not carry an exit code: %+v", e.ExitCode)
		}
		if e.SenderPID != 0 {
			t.Fatalf("delivered-to-exit fact must not claim a sender: %d", e.SenderPID)
		}
	})

	t.Run("signal", func(t *testing.T) {
		evs, stats := collect(t, "../../testdata/trace/signal.bin")
		if stats.Events != 1 {
			t.Fatalf("stats: %+v", stats)
		}
		e := evs[0]
		if e.Type != EventSIGNAL || e.Signal != 15 || e.Fact != SignalSent {
			t.Fatalf("signal event: %+v", e)
		}
		// SIGNAL_SENT: sender is known and must be recorded, but delivery
		// remains a separate fact (6.13/6.14).
		if e.SenderPID == 0 {
			t.Fatalf("signal_sent fixture must carry its sender: %+v", e)
		}
	})

	t.Run("process-stop", func(t *testing.T) {
		evs, stats := collect(t, "../../testdata/trace/process-stop.bin")
		if stats.Events != 1 {
			t.Fatalf("stats: %+v", stats)
		}
		e := evs[0]
		if e.Type != EventSTOP || e.Fact != SignalObservedStop {
			t.Fatalf("stop event: %+v", e)
		}
	})

	t.Run("oom", func(t *testing.T) {
		evs, stats := collect(t, "../../testdata/trace/oom.bin")
		if stats.Events != 1 {
			t.Fatalf("stats: %+v", stats)
		}
		e := evs[0]
		if e.Type != EventOOM {
			t.Fatalf("oom event: %+v", e)
		}
		// OOM events stay capability-gated at runtime (never faked), but the
		// wire record itself travels like any other event.
		if e.ExitCode == nil || *e.ExitCode != 137 {
			t.Fatalf("oom victim status: %+v", e.ExitCode)
		}
	})

	t.Run("dropped-events", func(t *testing.T) {
		evs, stats := collect(t, "../../testdata/trace/dropped-events.bin")
		if stats.Events != 4 {
			t.Fatalf("stats: %+v", stats)
		}
		// sequences 1,2,3,5: exactly one visible gap (6.26).
		if stats.Lost != 1 {
			t.Fatalf("expected lost=1 from sequence gap, got %d", stats.Lost)
		}
		if evs[3].Sequence != 5 {
			t.Fatalf("sequence expectation: %+v", evs)
		}
	})

	t.Run("unknown-version", func(t *testing.T) {
		evs, stats := collect(t, "../../testdata/trace/unknown-version.bin")
		// A mistyped payload is a bad sample: counted loudly, not decoded,
		// never silently dropped (6.43/6.57).
		if stats.Events != 0 || stats.BadSamples != 1 || len(evs) != 0 {
			t.Fatalf("stats: %+v evs=%+v", stats, evs)
		}
	})
}

func TestGatewayReplayRejectsBrokenFraming(t *testing.T) {
	// truncated payload beyond a complete frame: fatal to the stream, and
	// the events decoded before it are still valid evidence.
	var evs []TraceEvent
	_, err := ReplayFile("../../testdata/trace/process-exec.bin", func(e TraceEvent) {
		evs = append(evs, e)
	})
	if err != nil {
		t.Fatalf("clean fixture replayed: %v", err)
	}
	if len(evs) != 1 {
		t.Fatalf("evs: %+v", evs)
	}
}
